"""Patch current live DEV archives only. Default: prepare. Use --deploy to apply."""
import argparse
import base64
import copy
import hashlib
import io
import json
from pathlib import Path
import subprocess
import tempfile
import urllib.request
import zipfile
from datetime import datetime, timezone

API = 'elettro-brand-os-dev-api'
REGION = 'us-east-1'
# Embedded sources and exact inspected baseline hashes are filled during packaging.
PAYLOAD = {'worker': {'baseline': {'index.mjs': 'dMe1Y3bSydoCrVSRkoIdHMAaEc0/TGnmUz1F2zx2dpI='}, 'files': {'index.mjs': '', 'claude-folder-relay.mjs': ''}}, 'api': {'baseline': {'claude-folder-ops.mjs': '9IgzZebSEzkUMgMsUwGQWCG3z23uxSOaJ/96xD0Rv70='}, 'files': {'claude-folder-ops.mjs': ''}}}

def digest(data):
    return base64.b64encode(hashlib.sha256(data).digest()).decode()

def prepare_archive(original, replacements):
    source = zipfile.ZipFile(io.BytesIO(original))
    names = source.namelist()
    if len(names) != len(set(names)):
        raise RuntimeError('Duplicate archive entries. Stopped.')
    output = io.BytesIO()
    with zipfile.ZipFile(output, 'w', zipfile.ZIP_DEFLATED) as target:
        target.comment = source.comment
        for item in source.infolist():
            target.writestr(copy.copy(item), replacements.get(item.filename, source.read(item.filename)))
        for name, data in replacements.items():
            if name not in names:
                target.writestr(name, data)
    result = output.getvalue()
    checked = zipfile.ZipFile(io.BytesIO(result))
    for name in names:
        if name not in replacements and checked.read(name) != source.read(name):
            raise RuntimeError('Unrelated archive content changed: ' + name)
    return result

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--deploy', action='store_true')
    args = parser.parse_args()
    import boto3
    client = boto3.client('lambda', region_name=REGION)
    api_config = client.get_function_configuration(FunctionName=API)
    worker = api_config['Environment']['Variables']['DROPBOX_SYNC_FUNCTION_NAME']
    if worker == API:
        raise RuntimeError('Worker unexpectedly points to API')
    prepared = {}
    stamp = datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')
    for label, function in [('worker', worker), ('api', API)]:
        live = client.get_function(FunctionName=function)
        config = live['Configuration']
        with urllib.request.urlopen(live['Code']['Location'], timeout=90) as response:
            original = response.read()
        if digest(original) != config['CodeSha256']:
            raise RuntimeError('Live download hash mismatch: ' + label)
        backup = Path(label + '-before-folder-network-' + stamp + '.zip').resolve()
        backup.write_bytes(original)
        backup.with_suffix('.config.json').write_text(json.dumps({
            'FunctionName': config['FunctionName'], 'Timeout': config['Timeout'],
            'CodeSha256': config['CodeSha256'], 'RevisionId': config['RevisionId']}, indent=2))
        print('Saved backup:', backup)
        archive = zipfile.ZipFile(io.BytesIO(original))
        replacements = {name: base64.b64decode(value) for name, value in PAYLOAD[label]['files'].items()}
        for name, expected in PAYLOAD[label]['baseline'].items():
            current = archive.read(name)
            if digest(current) != expected and current != replacements.get(name):
                raise RuntimeError('Live source changed since inspection: ' + label + '/' + name + '. No deployment attempted.')
        # Adding a new module must never replace an unrelated pre-existing module.
        for name, data in replacements.items():
            if name not in PAYLOAD[label]['baseline'] and name in archive.namelist() and archive.read(name) != data:
                raise RuntimeError('Unexpected existing module: ' + name)
        if label == 'api':
            index = archive.read('index.mjs').decode()
            for marker in ['claude-folder-ops.mjs','completeDropboxUpload','handleDropboxUploadSession','preserveWorkflowState']:
                if marker not in index:
                    raise RuntimeError('API baseline missing ' + marker)
        with tempfile.TemporaryDirectory() as directory:
            for name, data in replacements.items():
                path = Path(directory) / name
                path.write_bytes(data)
                subprocess.run(['node', '--check', str(path)], check=True, capture_output=True)
        patched = prepare_archive(original, replacements)
        path = Path(label + '-folder-network-fixed.zip').resolve()
        path.write_bytes(patched)
        prepared[label] = (function, config, patched)
        print('Prepared:', path, '(all other ZIP entries preserved)')
    if not args.deploy:
        print('Preparation passed. Run with --deploy to apply.')
        return
    # Deploy the additive worker handler first. Existing worker actions stay intact.
    for label in ['worker', 'api']:
        function, config, patched = prepared[label]
        current = client.get_function_configuration(FunctionName=function)
        if current['RevisionId'] != config['RevisionId']:
            raise RuntimeError('Concurrent configuration/code change detected for ' + label)
        if label == 'api' and current['Timeout'] < 60:
            client.update_function_configuration(FunctionName=function, Timeout=60, RevisionId=current['RevisionId'])
            client.get_waiter('function_updated_v2').wait(FunctionName=function)
            current = client.get_function_configuration(FunctionName=function)
            if current['CodeSha256'] != config['CodeSha256']:
                raise RuntimeError('API code changed during timeout update')
        client.update_function_code(FunctionName=function, ZipFile=patched, RevisionId=current['RevisionId'])
        client.get_waiter('function_updated_v2').wait(FunctionName=function)
        verified = client.get_function_configuration(FunctionName=function)
        if verified['CodeSha256'] != digest(patched):
            raise RuntimeError('Deployed hash mismatch: ' + label)
        print('Verified deployment:', label)
        if label == 'worker':
            probe = client.invoke(FunctionName=function, InvocationType='RequestResponse', Payload=json.dumps({
                'action':'claude-folder-relay-v1','brandSlug':'elettro','endpoint':'get_metadata',
                'body':{'path':'/1---elettro-brand-os/brands/elettro'}}).encode())
            result = json.loads(probe['Payload'].read())
            if probe.get('FunctionError') or result.get('ok') is not True or result.get('result',{}).get('.tag') != 'folder':
                raise RuntimeError('Worker read-only Dropbox check failed. API patch was not deployed: ' + str(result.get('error','unexpected response')))
            print('Worker read-only Dropbox folder check passed.')
    print('Folder network fix deployed. No folders or assets were changed by this script.')
    print('Next: read the test folder by its Dropbox ID, then retry the disposable-folder rename once.')

if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        raise SystemExit('STOP: ' + str(error)) from None
